import { Component, ViewChild, AfterViewInit, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { BehaviorSubject } from 'rxjs';
import { DataSourceComponent, ListGridComponent, MetaInfo, MetadatiColonna, MetadatiTabella } from 'wuic-framework-lib';

@Component({
  selector: 'app-external-rest-grid',
  standalone: true,
  imports: [DataSourceComponent, ListGridComponent],
  templateUrl: './external-rest-grid.component.html'
})
export class ExternalRestGridComponent implements AfterViewInit {
  @ViewChild('ds') ds!: DataSourceComponent;
  private http = inject(HttpClient);

  ngAfterViewInit() {
    this.http.get<any[]>('https://jsonplaceholder.typicode.com/posts')
      .subscribe(rows => this.fill(rows));
  }

  private fill(rows: any[]) {
    const meta = new MetaInfo();
    // IMPORTANTE: usare `new MetadatiTabella()` per ereditare i default sani
    // (md_sortable, md_pageable, ecc.). Un object literal lascerebbe
    // md_sortable=undefined -> p-table non renderebbe le colonne come ordinabili.
    const tableMeta = new MetadatiTabella('posts');
    tableMeta.md_server_side_operations = false;  // forza client-side
    tableMeta.md_pageable = true;
    tableMeta.md_pagesize = 10;
    meta.tableMetadata = tableMeta;
    // Helper tipato: vincola `props` a `Partial<MetadatiColonna>` per avere
    // autocomplete su ogni `mc_...` (Object.assign nudo non lo offre).
    const col = (name: string, props: Partial<MetadatiColonna>) =>
      Object.assign(new MetadatiColonna(name), props);

    meta.columnMetadata = [
      col('id',    { mc_display_string_in_view: 'ID',    mc_ui_column_type: 'number' }),
      // mc_show_in_filters: true abilita la box di filtro sotto l'header.
      col('title', { mc_display_string_in_view: 'Title', mc_ui_column_type: 'text', mc_show_in_filters: true }),
      col('body',  { mc_display_string_in_view: 'Body',  mc_ui_column_type: 'text', mc_show_in_filters: true })
    ];
    this.ds.metaInfo = meta;
    this.ds.fetchInfo$.next({
      resultInfo: { dato: rows, totalRowCount: rows.length, current: {} } as any,
      metaInfo: meta,
      filterDescriptor: {}
    });
  }
}

