import { Component, ViewChild, AfterViewInit, inject } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { BehaviorSubject } from 'rxjs';
import { DataSourceComponent, ListGridComponent, MetaInfo, MetadatiColonna, MetadatiTabella, WtoolboxService } from 'wuic-framework-lib';

interface InventoryResponse { rows: any[]; total: number; }

@Component({
  selector: 'app-server-side-grid',
  standalone: true,
  imports: [DataSourceComponent, ListGridComponent],
  template: `
    <wuic-data-source #ds></wuic-data-source>
    <wuic-list-grid
      [hardcodedDatasource]="ds"
      (onPaging)="reloadFromServer()"
      (onSorting)="reloadFromServer()"
      (onFiltering)="reloadFromServer()"></wuic-list-grid>
  `
})
export class ServerSideGridComponent implements AfterViewInit {
  @ViewChild('ds') ds!: DataSourceComponent;
  private http = inject(HttpClient);
  private meta!: MetaInfo;
  private fd!: { [k: string]: BehaviorSubject<any> };

  ngAfterViewInit() {
    this.initMeta();
    this.reloadFromServer();
  }

  reloadFromServer(): void {
    const page     = Number(this.ds?.currentPage || 1);
    const pageSize = Number(this.ds?.pageSize || 10);
    const sort     = this.ds?.sortInfo?.[0];
    const filter   = this.ds?.filterInfo?.filters?.[0];

    let params = new HttpParams()
      .set('offset', String((page - 1) * pageSize))
      .set('limit',  String(pageSize));

    if (sort?.field) {
      params = params.set('sortField', String(sort.field))
                     .set('sortDir',   String(sort.dir || 'asc'));
    }
    if (filter?.field && filter?.value) {
      params = params.set('filterField', String(filter.field))
                     .set('filterValue', String(filter.value))
                     .set('filterOp',    String(filter.operatore || 'contains'));
    }

    // Usa l'URL assoluta del backend o `WtoolboxService.appSettings.api_url`
    // se il tuo dev server frontend non e' co-locato col backend (caso tipico
    // Angular `:4200` + ASP.NET `:5000` senza proxy.conf.json).
    this.http.get<InventoryResponse>('http://localhost:5000/api/samples/inventory', { params })
      .subscribe(res => {
        this.ds.fetchInfo$.next({
          resultInfo: { dato: res.rows, totalRowCount: res.total, current: {} } as any,
          metaInfo: this.meta,
          filterDescriptor: this.fd
        });
      });
  }

  private initMeta(): void {
    const meta = new MetaInfo();
    const tableMeta = new MetadatiTabella('inventory');
    // md_server_side_operations resta `true` (default) -> p-table in [lazy]="true",
    // niente sort/filter/paging interno: ricarichiamo la pagina giusta da server.
    tableMeta.md_pageable = true;
    tableMeta.md_pagesize = 10;
    meta.tableMetadata = tableMeta;

    const col = (n: string, p: Partial<MetadatiColonna>) => Object.assign(new MetadatiColonna(n), p);
    meta.columnMetadata = [
      col('id',   { mc_display_string_in_view: 'ID',      mc_ui_column_type: 'number', mc_is_primary_key: true }),
      col('name', { mc_display_string_in_view: 'Product', mc_ui_column_type: 'text',   mc_show_in_filters: true })
    ];

    const fd: { [k: string]: BehaviorSubject<any> } = {};
    meta.columnMetadata.forEach(c => fd[c.mc_nome_colonna] = new BehaviorSubject<any>(null));

    this.meta = meta;
    this.fd = fd;
    this.ds.metaInfo = meta;
    this.ds.filterDescriptor = fd;
  }
}

[HttpGet("inventory")]
public IActionResult GetInventory(
    int offset = 0,
    int limit = 10,
    string? sortField = null,
    string? sortDir = "asc",
    string? filterField = null,
    string? filterValue = null,
    string? filterOp = "contains")
{
    IEnumerable<InventoryItem> q = _inventory;

    // 1) filter prima del count: total deve essere POST-filter / PRE-page,
    //    altrimenti il pager UI mostra pagine vuote.
    if (!string.IsNullOrWhiteSpace(filterField) && !string.IsNullOrWhiteSpace(filterValue))
        q = ApplyInventoryFilter(q, filterField, filterValue, filterOp ?? "contains");

    var total = q.Count();

    // 2) sort
    if (!string.IsNullOrWhiteSpace(sortField))
        q = ApplyInventorySort(q, sortField, (sortDir ?? "asc").ToLowerInvariant());

    // 3) page
    var rows = q.Skip(Math.Max(0, offset)).Take(Math.Max(1, limit)).ToList();

    return Ok(new { rows, total });
}

import { Component, ViewChild, AfterViewInit, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { BehaviorSubject, forkJoin } from 'rxjs';
import {
  DataProviderOdataService,
  DataSourceComponent, ListGridComponent,
  FilterInfo, MetaInfo, MetadatiColonna, MetadatiTabella,
  WtoolboxService
} from 'wuic-framework-lib';

@Component({ /* ... */ })
export class ODataCitiesGridComponent implements AfterViewInit {
  @ViewChild('ds') ds!: DataSourceComponent;
  private http = inject(HttpClient);
  private odataSrv = inject(DataProviderOdataService);
  // ... meta, fd init (come 3b) ...

  reloadFromServer(): void {
    const page     = Number(this.ds?.currentPage || 1);
    const pageSize = Number(this.ds?.pageSize || 10);
    const sort     = this.ds?.sortInfo?.[0];
    const filter   = (this.ds?.filterInfo || new FilterInfo('AND', [])) as FilterInfo;
    const base     = String(WtoolboxService.appSettings.file_path || '').replace(/\/$/, '');

    // 1) URL con $filter gia' tradotto dal framework:
    //    es. '/odata/Cities?$filter=contains(cityName%2C%20%27Mil%27)'
    const baseRelUrl = this.odataSrv.filterInfoToOdata(filter, 'Cities');
    const sep = baseRelUrl.includes('?') ? '&' : '?';

    // 2) Aggiungi $top/$skip/$orderby come extra query params
    const pageExtras = [ `$top=${pageSize}`, `$skip=${(page - 1) * pageSize}` ];
    if (sort?.field) {
      pageExtras.push(`$orderby=${encodeURIComponent(`${sort.field} ${sort.dir || 'asc'}`)}`);
    }
    const pageUrl = `${base}${baseRelUrl}${sep}${pageExtras.join('&')}`;

    // 3) Count query: stesso filter, $select=cityID per payload minimo
    const countUrl = `${base}${baseRelUrl}${sep}$select=cityID`;

    forkJoin({
      page: this.http.get<any[]>(pageUrl),
      all:  this.http.get<any[]>(countUrl)
    }).subscribe(({ page, all }) => {
      this.ds.fetchInfo$.next({
        resultInfo: { dato: page, totalRowCount: all.length, current: {} } as any,
        metaInfo: this.meta,
        filterDescriptor: this.fd
      });
    });
  }
}

