interface TaskItem { id: number; title: string; done: boolean; }

@Component({
  selector: 'app-tasks',
  standalone: true,
  templateUrl: './tasks.component.html'
})
export class TasksComponent implements OnInit {
  private http = inject(HttpClient);
  tasks = signal<TaskItem[]>([]);

  ngOnInit() { this.reload(); }
  reload() { this.http.get<TaskItem[]>('/api/samples/tasks').subscribe(r => this.tasks.set(r)); }
  toggle(row: TaskItem) { this.http.put(`/api/samples/tasks/${row.id}`, row).subscribe(); }
  remove(row: TaskItem) { this.http.delete(`/api/samples/tasks/${row.id}`).subscribe(_ => this.reload()); }
}

[HttpGet("tasks")]
public IActionResult GetTasks() => Ok(_tasks);

[HttpPost("tasks")]
public IActionResult AddTask([FromBody] TaskItem item)
{
    item.Id = _tasks.Count == 0 ? 1 : _tasks.Max(t => t.Id) + 1;
    _tasks.Add(item);
    return Created($"/api/samples/tasks/{item.Id}", item);
}

[HttpPut("tasks/{id:int}")]
public IActionResult UpdateTask(int id, [FromBody] TaskItem item)
{
    var existing = _tasks.FirstOrDefault(t => t.Id == id);
    if (existing == null) return NotFound();
    existing.Title = item.Title;
    existing.Done = item.Done;
    return NoContent();
}

[HttpDelete("tasks/{id:int}")]
public IActionResult DeleteTask(int id)
{
    _tasks.RemoveAll(t => t.Id == id);
    return NoContent();
}

