export class AziendeGridComponent implements OnInit {
  @ViewChild('ds', { static: true }) ds!: DataSourceComponent;

  ngOnInit() {
    this.ds.fetchInfo$.subscribe(info => {
      const tm = info?.metaInfo?.tableMetadata;
      if (!tm) return;
      // idempotente: fetchInfo$ è un BehaviorSubject e riemette
      if (tm._Metadati_Custom_Actions_Tabelles.some(a => a.button_caption === 'Esporta selezionati')) return;
      tm.md_multiple_selection = true; // selezione multipla (= mdmultipleselection=1 via SQL)
      tm._Metadati_Custom_Actions_Tabelles.push({
        button_caption: 'Esporta selezionati',
        button_image: 'pi pi-download',
        action_callback__fn: (datasource, metaInfo, record, event, wtoolbox) => {
          const ids = (datasource.resultInfo?.selected ?? []).map((r: any) => r.id?.value);
          datasource.fetchData(); // refresh UI dopo l'azione (NON refresh())
          wtoolbox.messageNotificationService.add({ severity: 'success', summary: 'Export', detail: ids.length + '' });
        },
      } as any);
    });
  }
}

