GlobalHandler.messageNotification.subscribe((data) => {
  const exc = data?.exception;
  if (!exc?.errorCode) return;

  // Filtra rumore noto.
  if (String(exc.errorCode).startsWith('errors.client.archetype.')) return;

  // Invio a endpoint analytics (Sentry, App Insights, ecc.).
  fetch('/analytics/client-errors', {
    method: 'POST',
    body: JSON.stringify({
      errorCode: exc.errorCode,
      args:      exc.args,
      traceId:   exc.traceId,
      url:       window.location.href,
      ts:        new Date().toISOString(),
    }),
    credentials: 'include',
  });
});

import { ErrorHandler, Injectable } from '@angular/core';
import { GlobalHandler } from './wuic-bridges/core';

@Injectable()
export class MyCustomErrorHandler extends GlobalHandler {
  override handleError(e: any): void {
    // 1. Suppress noise non azionabile.
    const msg = (typeof e?.message === 'string' ? e.message : '') as string;
    if (msg.includes('ResizeObserver loop limit exceeded')) {
      console.debug('[MyCustomErrorHandler] suppressed:', msg);
      return;
    }

    // 2. Arricchisci args con context applicativo.
    if (typeof e?.error?.errorCode === 'string' && e?.error?.args) {
      e.error.args = {
        ...e.error.args,
        appVersion: (window as any).__myAppVersion || 'dev',
        userRole:   (window as any).__myAppUserRole || 'unknown',
      };
    }

    // 3. Delega al default — tutte le typed envelopes, traduzioni,
    //    dialog SQL passthrough, NG04002 routing continuano a funzionare.
    super.handleError(e);
  }
}

